if (!root) {
    root = new TreeNode(item);
    return;
}
if (item < root->val) {
    avlInsert(root->left, item);
} else if (item > root->val) {
    avlInsert(root->right, item);
} else {
    return; // Duplicate keys not allowed
}
root->height = 1 + std::max(getHeight(root->left), getHeight(root->right));
int balance = getBalance(root);
if (balance > 1 && item < root->left->val) {
    rightRotate(root);
} else if (balance < -1 && item > root->right->val) {
    leftRotate(root);
} else if (balance > 1 && item > root->left->val) {
    leftRotate(root->left);
    rightRotate(root);
} else if (balance < -1 && item < root->right->val) {
    rightRotate(root->right);
    leftRotate(root);
}

